module tb_TopModule;
    logic       clk;
    logic [7:0] d;
    logic [7:0] q;

    TopModule uut (
        .clk(clk),
        .d(d),
        .q(q)
    );

    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    initial begin
        d = 8'h00;
        @(posedge clk);
        #1;
        if (q !== 8'h00) begin
            $display("SELFTEST FAIL: Initial value mismatch. Expected 00, got %h", q);
            $finish;
        end

        d = 8'hA5;
        @(posedge clk);
        #1;
        if (q !== 8'hA5) begin
            $display("SELFTEST FAIL: Expected A5, got %h", q);
            $finish;
        end

        d = 8'h5A;
        @(posedge clk);
        #1;
        if (q !== 8'h5A) begin
            $display("SELFTEST FAIL: Expected 5A, got %h", q);
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
